\documentclass{article}
\usepackage{pgfplots}
\pgfplotsset{compat=1.18}
\usepackage{pgfplotstable}

\begin{document}

\begin{tikzpicture}
\begin{axis}[
    width=10cm,
    height=6cm,
    xlabel={X轴},
    ylabel={Y轴},
    title={粉红色折线图示例},
    grid=major,
    legend style={at={(0.98,0.02)}, anchor=south east},
    xmin=0, xmax=10,
    ymin=0, ymax=100,
    xtick={0,2,4,6,8,10},
    ytick={0,20,40,60,80,100},
]

% 粉红色折线数据
\addplot[
    color=pink!80!red,
    mark=*,
    mark options={fill=pink!50},
    thick,
    smooth
] coordinates {
    (0, 10)
    (1, 25)
    (2, 45)
    (3, 30)
    (4, 60)
    (5, 75)
    (6, 50)
    (7, 85)
    (8, 65)
    (9, 95)
    (10, 70)
};

\addlegendentry{粉红色折线}

\end{axis}
\end{tikzpicture}

\end{document}
